py\n├── src/\n│   └── koffer/\n│       ├── __init__.py\n│       ├── __main__.py\n│       ├── app.py\n│       ├── config/\n│       ├── domain/\n│       ├── persistence/\n│       │   └── migrations/\n│       ├── repositories/\n│       ├── services/\n│       ├── jobs/\n│       ├── filesystem/\n│       ├── metadata/\n│       ├── audio/\n│       ├── analysis/\n│       ├── similarity/\n│       ├── ui/\n│       │   ├── shell/\n│       │   ├── screens/\n│       │   ├── widgets/\n│       │   ├── models/\n│       │   └── resources/\n│       └── diagnostics/\n├── tests/\n│   ├── unit/\n│   ├── integration/\n│   ├── ui/\n│   ├── e2e/\n│   ├── fixtures/\n│   └── performance/\n└── docs/\n~~~\n\nDo not create a giant `utils.py`, god service, or monolithic MainWindow.\n\n## Layer responsibilities\n\n### domain\n\nPure application concepts and rules:\n- Source;\n- Sample;\n- Collection;\n- Suggestion;\n- classification values;\n- preparation recipe;\n- file operation plan;\n- Job state;\n- error/result types.\n\nDomain code must be testable without Qt, SQLite, FFmpeg, or filesystem side effects.\n\n### persistence\n\nOwns:\n- SQLite connection factory;\n- migrations;\n- transactions;\n- FTS maintenance;\n- database backup/restore primitives.\n\nUI code never executes SQL.\n\n### repositories\n\nTyped persistence interfaces for:\n- Sources;\n- Samples;\n- Collections;\n- metadata/classifications;","isEmpty":false,"exceededLimit":false,"totalLines":296,"fileSize":7784,"path":"/home/sean/Documents/experiments/csw-041026/koffer/docs/16-system-architecture.md","readRange":{"startLine":1,"endLine":120},"relatedCursorRulePaths":[],"relatedCursorRules":[]}}},"hookAdditionalContexts":[],"toolCallId":"call-ed3c14c0-83e7-463b-b586-b9fa81d16eb0-9\nfc_p3vLSNk-3LYxF7-fe4704f8-aws_ue1_0","startedAtMs":"1791144831070","completedAtMs":"1791144831352"},"model_call_id":"7f08ae26-8292-49b2-9e41-cdc985231bed-2-l6s4","session_id":"b3e6f58c-23c0-4d08-ae18-617e61c16dc2","timestamp_ms":1791144831326}
