{"type":"tool_call","subtype":"started","call_id":"call-eff138b2-6500-4e3a-b37b-8dfaec60885b-41\nfc_p3vQV9N-6jKPYy-75702dfc-aws_ue1_1","tool_call":{"editToolCall":{"args":{"path":"/home/sean/Documents/experiments/csw-041026/.dreadnought/scratch/koffer/work/src/koffer/persistence/migrations.py","streamContent":"\"\"\"Append-only SQL migration runner with checksum tracking.\"\"\"\n\nfrom __future__ import annotations\n\nimport hashlib\nimport re\nimport sqlite3\nfrom dataclasses import dataclass\nfrom importlib import resources\nfrom pathlib import Path\n\nfrom koffer.domain.timestamps import utc_now_iso\n\n_MIGRATION_NAME_RE = re.compile(r\"^(\\d{3})_.+\\.sql$\")\n\n\nclass MigrationError(RuntimeError):\n    \"\"\"Raised when migrations cannot be applied safely.\"\"\"\n\n\n@dataclass(frozen=True, slots=True)\nclass MigrationFile:\n    version: int\n    name: str\n    sql: str\n    checksum: str\n\n\ndef _checksum(sql: str) -> str:\n    return hashlib.sha256(sql.encode(\"utf-8\")).hexdigest()\n\n\ndef _load_migrations_from_dir(directory: Path) -> list[MigrationFile]:\n    files: list[MigrationFile] = []\n    for path in sorted(directory.glob(\"*.sql\")):\n        match = _MIGRATION_NAME_RE.match(path.name)\n        if match is None:\n            msg = f\"invalid migration filename: {path.name}\"\n            raise MigrationError(msg)\n        sql = path.read_text(encoding=\"utf-8\")\n        files.append(\n            MigrationFile(\n                version=int(match.group(1)),\n                name=path.name,\n                sql=sql,\n                checksum=_checksum(sql),\n            )\n        )\n    return files\n\n\ndef discover_migrations(migrations_dir: Path | None = None) -> list[MigrationFile]:\n    \"\"\"Load packaged or filesystem migration SQL files in version order.\"\"\"\n    if migrations_dir is not None:\n        return _load_migrations_from_dir(migrations_dir)\n\n    package = resources.files(\"koffer.persistence\").joinpath(\"migrations\")\n    files: list[MigrationFile] = []\n    for item in sorted(package.iterdir(), key=lambda p: p.name):\n        if not item.name.endswith(\".sql\"):\n            continue\n        match = _MIGRATION_NAME_RE.match(item.name)\n        if match is None:\n            msg = f\"invalid migration filename: {item.name}\"\n            raise MigrationError(msg)\n        sql = item.read_text(encoding=\"utf-8\")\n        files.append(\n            MigrationFile(\n                version=int(match.group(1)),\n                name=item.name,\n                sql=sql,\n                checksum=_checksum(sql),\n            )\n        )\n    if not files:\n        # Editable installs may not package non-.py data; fall back to source path.\n        fallback = Path(__file__).resolve().parent / \"migrations\"\n        files = _load_migrations_from_dir(fallback)\n    return files\n\n\ndef ensure_schema_migrations_table(conn: sqlite3.Connection) -> None:\n    conn.execute(\n        \"\"\"\n        CREATE TABLE IF NOT EXISTS schema_migrations (\n            version INTEGER PRIMARY KEY NOT NULL,\n            applied_at TEXT NOT NULL,\n            checksum TEXT NOT NULL\n        )\n        \"\"\"\n    )\n\n\ndef _applied_versions(conn: sqlite3.Connection) -> dict[int, str]:\n    rows = conn.execute(\n        \"SELECT version, checksum FROM schema_migrations ORDER BY version\"\n    ).fetchall()\n    return {int(row[0]): str(row[1]) for row in rows}\n\n\nclass MigrationRunner:\n    \"\"\"Apply pending migrations inside explicit transactions.\"\"\"\n\n    def __init__(\n        self,\n        conn: sqlite3.Connection,\n        *,\n        migrations: list[MigrationFile] | None = None,\n        migrations_dir: Path | None = None,\n    ) -> None:\n        self._conn = conn\n        self._migrations = migrations if migrations is not None else discover_migrations(\n            migrations_dir\n        )\n\n    @property\n    def migrations(self) -> list[MigrationFile]:\n        return list(self._migratio