    return applied_now\n\n    def _apply_one(self, migration: MigrationFile) -> None:\n        conn = self._conn\n        conn.execute(\"BEGIN IMMEDIATE\")\n        try:\n            for statement in _iter_sql_statements(migration.sql):\n                conn.execute(statement)\n            conn.execute(\n                \"\"\"\n                INSERT INTO schema_migrations (version, applied_at, checksum)\n                VALUES (?, ?, ?)\n                \"\"\",\n                (migration.version, utc_now_iso(), migration.checksum),\n            )\n            conn.execute(\"COMMIT\")\n        except Exception:\n            with contextlib.suppress(sqlite3.Error):\n                conn.execute(\"ROLLBACK\")\n            raise\n\n\ndef apply_migrations(conn: sqlite3.Connection, *, migrations_dir: Path | None = None) -> list[int]:\n    \"\"\"Convenience wrapper used by tests and future startup wiring.\"\"\"\n    return MigrationRunner(conn, migrations_dir=migrations_dir).apply_pending()\n","message":"The file /home/sean/Documents/experiments/csw-041026/.dreadnought/scratch/koffer/work/src/koffer/persistence/migrations.py has been updated."}}},"hookAdditionalContexts":[],"toolCallId":"call-713775d8-d563-4024-b712-67a3ce71d43c-51\nfc_p3vQkNi-6jKPYy-895e98da-aws_ue1_1","startedAtMs":"1791145672406","completedAtMs":"1791145673430"},"model_call_id":"19530a35-237b-4d4e-9e99-7fa173d778a3-12-njdy","session_id":"8b8cd8da-a9e0-4991-a7df-842d0f013e1e","timestamp_ms":1791145673389}
