{"type":"tool_call","subtype":"completed","call_id":"call-7bbb8e88-efbb-49c7-9378-c39fa4e02e33-19\nfc_p3vT7vQ-3LYxF7-cd88a93c-aws_ue1_3","tool_call":{"readToolCall":{"args":{"path":"/home/sean/Documents/experiments/csw-041026/.dreadnought/scratch/koffer/work/src/koffer/persistence/connection.py"},"result":{"success":{"content":"\"\"\"SQLite connection factory with WAL, FKs, busy timeout, and thread ownership.\n\nConnections are cached per calling thread and must never be handed across threads.\n``sqlite3`` ``check_same_thread=True`` reinforces that invariant.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport sqlite3\nimport threading\nfrom pathlib import Path\n\nDEFAULT_BUSY_TIMEOUT_MS = 5000\n\n\nclass ConnectionFactory:\n    \"\"\"Create and cache per-thread SQLite connections for one database path.\"\"\"\n\n    def __init__(\n        self,\n        database_path: Path | str,\n        *,\n        busy_timeout_ms: int = DEFAULT_BUSY_TIMEOUT_MS,\n    ) -> None:\n        self._database_path = Path(database_path)\n        self._busy_timeout_ms = busy_timeout_ms\n        self._local = threading.local()\n\n    @property\n    def database_path(self) -> Path:\n        return self._database_path\n\n    def get_connection(self) -> sqlite3.Connection:\n        \"\"\"Return the calling thread's connection, creating it on first use.\"\"\"\n        existing: sqlite3.Connection | None = getattr(self._local, \"connection\", None)\n        if existing is not None:\n            owner: int | None = getattr(self._local, \"owner_ident\", None)\n            if owner != threading.get_ident():\n                msg = \"thread-local connection ownership violated\"\n                raise RuntimeError(msg)\n            return existing\n\n        conn = self.open_connection()\n        self._local.connection = conn\n        self._local.owner_ident = threading.get_ident()\n        return conn\n\n    def open_connection(self) -> sqlite3.Connection:\n        \"\"\"Open a new connection owned exclusively by the calling thread.\"\"\"\n        self._database_path.parent.mkdir(parents=True, exist_ok=True)\n        conn = sqlite3.connect(\n            self._database_path,\n            check_same_thread=True,\n            isolation_level=None,\n        )\n        conn.row_factory = sqlite3.Row\n        conn.execute(\"PRAGMA foreign_keys = ON\")\n        conn.execute(f\"PRAGMA busy_timeout = {int(self._busy_timeout_ms)}\")\n        # journal_mode=WAL is persistent; ignore return value shape differences.\n        conn.execute(\"PRAGMA journal_mode = WAL\")\n        return conn\n\n    def close_thread_connection(self) -> None:\n        \"\"\"Close and drop the connection cached for the calling thread.\"\"\"\n        conn = getattr(self._local, \"connection\", None)\n        if conn is not None:\n            conn.close()\n        self._local.connection = None\n        self._local.owner_ident = None\n","isEmpty":false,"exceededLimit":false,"totalLines":70,"fileSize":2475,"path":"/home/sean/Documents/experiments/csw-041026/.dreadnought/scratch/koffer/work/src/koffer/persistence/connection.py","readRange":{"startLine":1,"endLine":70},"relatedCursorRulePaths":[],"relatedCursorRules":[]}}},"hookAdditionalContexts":[],"toolCallId":"call-7bbb8e88-efbb-49c7-9378-c39fa4e02e33-19\nfc_p3vT7vQ-3LYxF7-cd88a93c-aws_ue1_3","startedAtMs":"1791146134870","completedAtMs":"1791146135000"},"model_call_id":"26bf19b6-86ee-4083-9345-1c9cee1a82d0-3-5pon","session_id":"804b0afb-6b1f-43a7-a037-00f71d27cf01","timestamp_ms":1791146134959}
