{"type":"tool_call","subtype":"started","call_id":"call-94d8ffed-62a4-480a-a5f9-a5d8f54dd943-52\nfc_p3vTLd2-3LYxF7-4c3798ab-aws_ue1_2","tool_call":{"editToolCall":{"args":{"path":"/home/sean/Documents/experiments/csw-041026/.dreadnought/scratch/koffer/work/src/koffer/repositories/exclusions.py","streamContent":"\"\"\"Typed Source exclusion repository. Caller owns the connection/transaction.\"\"\"\n\nfrom __future__ import annotations\n\nimport sqlite3\n\nfrom koffer.domain.enums import ExclusionPatternType\nfrom koffer.domain.ids import EntityId\nfrom koffer.domain.models import ExclusionRule\nfrom koffer.repositories._sqlite import as_entity_id, bool_to_int, int_to_bool, row_count\n\n\ndef _from_row(row: sqlite3.Row) -> ExclusionRule:\n    return ExclusionRule(\n        id=as_entity_id(row[\"id\"]),\n        source_id=as_entity_id(row[\"source_id\"]),\n        pattern=str(row[\"pattern\"]),\n        pattern_type=ExclusionPatternType(str(row[\"pattern_type\"])),\n        enabled=int_to_bool(row[\"enabled\"]),\n    )\n\n\nclass SourceExclusionRepository:\n    \"\"\"CRUD for per-Source exclusion rules.\"\"\"\n\n    def __init__(self, conn: sqlite3.Connection) -> None:\n        self._conn = conn\n\n    def list_for_source(self, source_id: EntityId) -> list[ExclusionRule]:\n        rows = self._conn.execute(\n            \"\"\"\n            SELECT * FROM source_exclusions\n            WHERE source_id = ?\n            ORDER BY pattern ASC, id ASC\n            \"\"\",\n            (str(source_id),),\n        ).fetchall()\n        return [_from_row(row) for row in rows]\n\n    def replace_for_source(\n        self, source_id: EntityId, rules: list[ExclusionRule]\n    ) -> list[ExclusionRule]:\n        \"\"\"Replace all exclusion rows for a Source with ``rules`` (atomic).\"\"\"\n        self._conn.execute(\"BEGIN IMMEDIATE\")\n        try:\n            self._conn.execute(\n                \"DELETE FROM source_exclusions WHERE source_id = ?\",\n                (str(source_id),),\n            )\n            stored: list[ExclusionRule] = []\n            for rule in rules:\n                row = ExclusionRule(\n                    id=rule.id,\n                    source_id=source_id,\n                    pattern=rule.pattern,\n                    pattern_type=rule.pattern_type,\n                    enabled=rule.enabled,\n                )\n                self._conn.execute(\n                    \"\"\"\n                    INSERT INTO source_exclusions (\n                        id, source_id, pattern, pattern_type, enabled\n                    ) VALUES (?, ?, ?, ?, ?)\n                    \"\"\",\n                    (\n                        str(row.id),\n                        str(row.source_id),\n                        row.pattern,\n                        str(row.pattern_type),\n                        bool_to_int(row.enabled),\n                    ),\n                )\n                stored.append(row)\n            self._conn.execute(\"COMMIT\")\n        except Exception:\n            self._conn.execute(\"ROLLBACK\")\n            raise\n        return stored\n\n    def delete_for_source(self, source_id: EntityId) -> int:\n        return row_count(\n            self._conn,\n            \"DELETE FROM source_exclusions WHERE source_id = ?\",\n            (str(source_id),),\n        )\n"}},"hookAdditionalContexts":[],"toolCallId":"call-94d8ffed-62a4-480a-a5f9-a5d8f54dd943-52\nfc_p3vTLd2-3LYxF7-4c3798ab-aws_ue1_2","startedAtMs":"1791146179957"},"model_call_id":"26bf19b6-86ee-4083-9345-1c9cee1a82d0-10-ig98","session_id":"804b0afb-6b1f-43a7-a037-00f71d27cf01","timestamp_ms":1791146182205}
