job.stage,\n                job.created_at,\n                job.started_at,\n                job.completed_at,\n                job.error_code,\n                job.summary_json,\n            ),\n        )\n\n    def get(self, job_id: EntityId) -> Job | None:\n        row = self._conn.execute(\n            \"SELECT * FROM jobs WHERE id = ?\",\n            (str(job_id),),\n        ).fetchone()\n        return None if row is None else _from_row(row)\n\n    def list_by_state(self, state: JobState) -> list[Job]:\n        rows = self._conn.execute(\n            \"\"\"\n            SELECT * FROM jobs\n            WHERE state = ?\n            ORDER BY created_at ASC, id ASC\n            \"\"\",\n            (str(state),),\n        ).fetchall()\n        return [_from_row(row) for row in rows]\n\n    def update(self, job: Job) -> bool:\n        return (\n            row_count(\n                self._conn,\n                \"\"\"\n                UPDATE jobs SET\n                    type = ?,\n                    state = ?,\n                    scope_json = ?,\n                    progress_current = ?,\n                    progress_total = ?,\n                    stage = ?,\n                    started_at = ?,\n                    completed_at = ?,\n                    error_code = ?,\n                    summary_json = ?\n                WHERE id = ?\n                \"\"\",\n                (\n                    str(job.type),\n                    str(job.state),\n                    job.scope_json,\n                    job.progress_current,\n                    job.progress_total,\n                    job.stage,\n                    job.started_at,\n                    job.completed_at,\n                    job.error_code,\n                    job.summary_json,\n                    str(job.id),\n                ),\n            )\n            > 0\n        )\n\n    def delete(self, job_id: EntityId) -> bool:\n        return (\n            row_count(\n                self._conn,\n                \"DELETE FROM jobs WHERE id = ?\",\n                (str(job_id),),\n            )\n            > 0\n        )\n","afterFullFileContent":"\"\"\"Typed Job repository for durable background work units.\"\"\"\n\nfrom __future__ import annotations\n\nimport sqlite3\n\nfrom koffer.domain.enums import JobState, JobType\nfrom koffer.domain.ids import EntityId\nfrom koffer.domain.models import Job\nfrom koffer.repositories._sqlite import as_entity_id, optional_int, optional_str, row_count\n\n\ndef _from_row(row: sqlite3.Row) -> Job:\n    return Job(\n        id=as_entity_id(row[\"id\"]),\n        type=JobType(str(row[\"type\"])),\n        state=JobState(str(row[\"state\"])),\n        scope_json=str(row[\"scope_json\"]),\n        progress_current=int(row[\"progress_current\"]),\n        created_at=str(row[\"created_at\"]),\n        progress_total=optional_int(row[\"progress_total\"]),\n        stage=optional_str(row[\"stage\"]),\n        started_at=optional_str(row[\"started_at\"]),\n        completed_at=optional_str(row[\"completed_at\"]),\n        error_code=optional_str(row[\"error_code\"]),\n        summary_json=optional_str(row[\"summary_json\"]),\n    )\n\n\nclass JobRepository:\n    \"\"\"CRUD for persisted Jobs (scheduler state only; no Qt types).\"\"\"\n\n    def __init__(self, conn: sqlite3.Connection) -> None:\n        self._conn = conn\n\n    def create(self, job: Job) -> None:\n        self._conn.execute(\n            \"\"\"\n            INSERT INTO jobs (\n                id, type, state, scope_json, progress_current, progress_total, stage,\n                created_at, started_at, completed_at, error_code, summary_json\n            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n            \"\"\",\n            (\n                str(job.id),\n                str(job.type),\n                str(job.state),\n                job.scope_json,\n                job.progress_current,\n                job.progress_total,\n                job.stage,\n                job.created_at,\n                job.started_at,\n                job.completed_at,\n                job.error_code,\n                job.summary_json,\n            ),\n        )\n\n    def get(self, job_id: EntityId) -> Job | None:\n        row = self._conn.execute(\n            \"SELECT * FROM jobs WHERE id = ?\",\n            (str(job_id),),\n        ).fetchone()\n        return None if row is None else _from_row(row)\n\n    def list_by_state(self, state: JobState) -> list[Job]:\n        rows = self._conn.execute(\n            \"\"\"\n            SELECT * FROM jobs\n            WHERE state = ?\n            ORDER BY created_at ASC, id ASC\n            \"\"\",\n            (str(state),),\n        ).fetchall()\n        return [_from_row(row) for row in rows]\n\n    def list_recent(self, *, limit: int = 100) -> list[Job]:\n        \"\"\"Newest-first Job rows for UI summaries (bounded).\"\"\"\n        rows = self._conn.execute(\n            \"\"\"\n            SELECT * FROM jobs\n            ORDER BY created_at DESC, id DESC\n            LIMIT ?\n            \"\"\",\n            (max(1, int(limit)),),\n        ).fetchall()\n        return [_from_row(row) for row in rows]\n\n    def update(self, job: Job) -> bool:\n        return (\n            row_count(\n                self._conn,\n                \"\"\"\n                UPDATE jobs SET\n                    type = ?,\n                    state = ?,\n                    scope_json = ?,\n                    progress_current = ?,\n                    progress_total = ?,\n                    stage = ?,\n                    started_at = ?,\n                    completed_at = ?,\n                    error_code = ?,\n                    summary_json = ?\n                WHERE id = ?\n                \"\"\",\n                (\n                    str(job.type),\n                    str(job.state),\n                    job.scope_json,\n                    job.progress_current,\n                    job.progress_total,\n                    job.stage,\n                    job.started_at,\n                    job.completed_at,\n                    job.error_code,\n                    job.summary_json,\n                    str(job.id),\n                ),\n            )\n            > 0\n        )\n\n    def delete(self, job_id: EntityId) -> bool:\n        return (\n            row_count(\n                self._conn,\n                \"DELETE FROM jobs WHERE id = ?\",\n                (str(job_id),),\n            )\n            > 0\n        )\n","message":"The file /home/sean/Documents/experiments/csw-041026/.dreadnought/scratch/koffer/work/src/koffer/repositories/jobs.py has been updated."}}},"hookAdditionalContexts":[],"toolCallId":"call-81fff02d-624a-445e-9397-1d9c67ca8579-48\nfc_p3vUNwu-6jKPYy-1c12614f-aws_ue1_0","startedAtMs":"1791146380096","completedAtMs":"1791146381570"},"model_call_id":"45f02ac6-dd47-4d69-be46-6e4759d0020f-11-frb1","session_id":"3787dc8c-fb4b-437d-a63e-5173987bf522","timestamp_ms":1791146381533}
