        root.setContentsMargins(48, 48, 48, 48)\n        root.setSpacing(20)\n\n        brand = QLabel(\"Koffer\")\n        brand.setObjectName(\"pageTitle\")\n        brand.setStyleSheet(f\"color: {CLAY}; font-size: 28px; font-weight: 700;\")\n        root.addWidget(brand)\n\n        title = QLabel(\"Welcome — index your sample library in place\")\n        title.setObjectName(\"pageTitle\")\n        root.addWidget(title)\n\n        body = QLabel(\n            \"Koffer scans directories you authorize. Scanning never moves or renames \"\n            \"your audio files. Core analysis stays local and works offline.\"\n        )\n        body.setObjectName(\"bodyText\")\n        body.setWordWrap(True)\n        root.addWidget(body)\n\n        promises = QHBoxLayout()\n        promises.setSpacing(12)\n        for heading, detail in (\n            (\"Files stay put\", \"Reference-first indexing. Adding a Source does not move audio.\"),\n            (\"Background scanning\", \"Discovery and analysis run as Jobs while you browse.\"),\n            (\"Works offline\", \"Your library remains usable when drives or networks drop.\"),\n        ):\n            card = QFrame()\n            card.setObjectName(\"promiseCard\")\n            card_layout = QVBoxLayout(card)\n            card_layout.setContentsMargins(16, 16, 16, 16)\n            heading_label = QLabel(heading)\n            heading_label.setObjectName(\"promiseTitle\")\n            detail_label = QLabel(detail)\n            detail_label.setObjectName(\"bodyText\")\n            detail_label.setWordWrap(True)\n            detail_label.setStyleSheet(f\"color: {MUTED};\")\n            card_layout.addWidget(heading_label)\n            card_layout.addWidget(detail_label)\n            promises.addWidget(card, stretch=1)\n        root.addLayout(promises)\n\n        actions = QHBoxLayout()\n        add_btn = QPushButton(\"Add First Source\")\n        add_btn.setObjectName(\"addFirstSourceButton\")\n        add_btn.setProperty(\"class\", \"primary\")\n        add_btn.setStyleSheet(\"\")  # styled via shell stylesheet #primaryButton\n        # Explicit object name used by stylesheet selector alias:\n        add_btn.setObjectName(\"addFirstSourceButton\")\n        add_btn.setAccessibleName(\"Add First Source\")\n        # Re-apply primary id for CSS after second setObjectName:\n        add_btn.setObjectName(\"primaryButton\")\n        add_btn.setProperty(\"kofferRole\", \"addFirstSource\")\n        # Keep a stable test handle via accessibleName + findChildren fallback.\n        self._add_button = add_btn\n        add_btn.clicked.connect(self.add_source_requested.emit)\n        actions.addWidget(add_btn)\n        actions.addStretch(1)\n        root.addLayout(actions)\n\n        drop_hint = QLabel(\"Or drop a sample folder onto this window.\")\n        drop_hint.setObjectName(\"bodyText\")\n        root.addWidget(drop_hint)\n        root.addStretch(1)\n\n        # Restore the stable object name expected by tests after stylesheet id.\n        self._add_button.setObjectName(\"addFirstSourceButton\")\n        # Keep primary visual via inline style matching tokens (shell also themes).\n        self._add_button.setStyleSheet(\n            \"QPushButton#addFirstSourceButton {\"\n            \" background-color: #CF8652; color: #0B0D0F; border: none;\"\n            \" border-radius: 5px; padding: 8px 16px; min-height: 32px;\"\n            \" font-weight: 600; }\"\n            \"QPushButton#addFirstSourceButton:hover { background-color: #E7A36F; }\"\n        )\n\n    @property\n    def add_button(self) -> QPushButton:\n        return self._add_button\n\n    def dragEnterEvent(self, event: QDragEnterEvent) -> None:  # noqa: N802\n        if event.mimeData().hasUrls():\n            for url in event.mimeData().urls():\n                local = url.toLocalFile()\n                if local and Path(local).is_dir():\n                    event.acceptProposedAction()\n                    return\n        event.ignore()\n\n    def dropEvent(self, event: QDropEvent) -> None:  # noqa: N802\n        for url in event.mimeData().urls():\n            local = url.toLocalFile()\n            if not local:\n                continue\n            path = Path(local)\n            if path.is_dir():\n                self.directory_dropped.emit(path)\n                event.acceptProposedAction()\n                return\n        event.ignore()\n","message":"Wrote contents to /home/sean/Documents/experiments/csw-041026/.dreadnought/scratch/koffer/work/src/koffer/ui/screens/welcome.py"}}},"hookAdditionalContexts":[],"toolCallId":"call-f0c13103-9455-400a-b7f9-ffcf5c26f612-54\nfc_p3vUR4L-6jKPYy-39cca5fc-aws_ue1_2","startedAtMs":"1791146387711","completedAtMs":"1791146392850"},"model_call_id":"45f02ac6-dd47-4d69-be46-6e4759d0020f-12-8v0q","session_id":"3787dc8c-fb4b-437d-a63e-5173987bf522","timestamp_ms":1791146392815}
