g)\n\n    source = sources.get(source_id)\n    if source is None:\n        failed = replace(\n            running,\n            state=JobState.FAILED,\n            stage=\"validate\",\n            completed_at=utc_now_iso(),\n            error_code=\"source_not_found\",\n            summary_json=json.dumps({\"error\": \"source_not_found\"}),\n        )\n        jobs.update(failed)\n        return failed\n\n    scanning = replace(\n        source,\n        status=SourceStatus.SCANNING,\n        last_scan_started_at=now,\n        updated_at=now,\n    )\n    sources.update(scanning)\n\n    rules = exclusions.list_for_source(source_id)\n    root = Path(source.root_path)\n\n    try:\n        progressing = replace(running, stage=\"enumerate\")\n        jobs.update(progressing)\n        discovered = enumerate_audio_files(\n            root,\n            recursive=source.recursive,\n            rules=rules,\n        )\n    except EnumerationFailed as exc:\n        return _fail_offline(\n            conn,\n            job=progressing,\n            source=scanning,\n            samples_repo=samples,\n            sources_repo=sources,\n            jobs_repo=jobs,\n            error=exc,\n        )\n\n    return _apply_discovery(\n        conn,\n        job=progressing,\n        source=scanning,\n        discovered=discovered,\n        mode=mode,\n        samples_repo=samples,\n        sources_repo=sources,\n        jobs_repo=jobs,\n        search=search,\n    )\n\n\ndef _fail_offline(\n    conn: sqlite3.Connection,\n    *,\n    job: Job,\n    source: Source,\n    samples_repo: SampleRepository,\n    sources_repo: SourceRepository,\n    jobs_repo: JobRepository,\n    error: EnumerationFailed,\n) -> Job:\n    \"\"\"Mark Source offline/unavailable without deleting or mass-missing Samples.\"\"\"\n    del conn  # connection owned by repositories\n    now = utc_now_iso()\n    if error.permission_denied:\n        status = SourceStatus.PERMISSION_DENIED\n        availability = SampleAvailability.PERMISSION_DENIED\n        error_code = \"permission_denied\"\n    else:\n        status = SourceStatus.OFFLINE\n        availability = SampleAvailability.SOURCE_OFFLINE\n        error_code = \"source_offline\"\n\n    # Preserve existing Sample rows; only update availability labels.\n    existing = samples_repo.list_by_source(source.id)\n    for sample in existing:\n        if sample.availability is SampleAvailability.MISSING:\n            continue\n        samples_repo.update(\n            replace(\n                sample,\n                availability=availability,\n                updated_at=now,\n            )\n        )\n\n    sources_repo.update(\n        replace(\n            source,\n            status=status,\n            last_scan_completed_at=now,\n            updated_at=now,\n        )\n    )\n    completed = replace(\n        job,\n        state=JobState.COMPLETED_WITH_ERRORS,\n        stage=\"offline\",\n        completed_at=now,\n        error_code=error_code,\n        progress_current=0,\n        progress_total=0,\n        summary_json=json.dumps(\n            {\n                \"error\": error_code,\n                \"message\": error.message,\n                \"samples_preserved\": len(existing),\n                \"marked_missing\": 0,\n                \"deleted\": 0,\n            }\n        ),\n    )\n    jobs_repo.update(completed)\n    return completed\n\n\ndef _apply_discovery(\n    conn: sqlite3.Connection,\n    *,\n    job: Job,\n    source: Source,\n    discovered: list[DiscoveredFile],\n    mode: ScanMode,\n    samples_repo: SampleRepository,\n    sources_repo: SourceRepository,\n    jobs_repo: JobRepository,\n    search: SearchIndexService,\n) -> Job:\n    del conn\n    now = utc_now_iso()\n    jobs_repo.update(\n        replace(\n            job,\n            stage=\"compare\",\n            progress_current=0,\n            progress_total=len(discovered),\n        )\n    )\n\n    existing = {s.relative_path: s for s in samples_repo.list_by_source(source.id)}\n    seen_paths: set[str] = set()\n    inserted = 0\n    updated = 0\n    unchanged = 0\n    fts_ids: list[EntityId] = []\n\n    for index, item in enumerate(discovered, start=1):\n        rel = normalize_relative_path(item.relative_path)\n        seen_paths.add(rel)\n        prior = existing.get(rel)\n        if prior is None:\n            sample = Sample(\n                id=new_entity_id(),\n                relative_path=rel,\n                normalized_path_cache=rel.lower(),\n                filename=item.filename,\n                extension=item.extension,\n                size_bytes=item.size_bytes,\n                mtime_ns=item.mtime_ns,\n                availability=SampleAvailability.ONLINE,\n                favorite=False,\n                first_seen_at=now,\n                last_seen_at=now,\n                created_at=now,\n                updated_at=now,\n                source_id=source.id,\n                device_id=item.device_id,\n                inode=item.inode,\n            )\n            samples_repo.create(sample)\n            fts_ids.append(sample.id)\n            inserted += 1\n        else:\n            same_identity = prior.size_bytes == item.size_bytes and prior.mtime_ns == item.mtime_ns\n            if mode is ScanMode.INCREMENTAL and same_identity:\n                samples_repo.update(\n                    replace(\n                        prior,\n                        availability=SampleAvailability.ONLINE,\n                        last_seen_at=now,\n                        updated_at=now,\n                        device_id=item.device_id,\n                        inode=item.inode,\n                    )\n                )\n                unchanged += 1\n            else:\n                availability = (\n                    SampleAvailability.ONLINE if same_identity else SampleAvailability.CHANGED\n                )\n                samples_repo.update(\n                    replace(\n                        prior,\n                        filename=item.filename,\n                        extension=item.extension,\n                        size_bytes=item.size_bytes,\n                        mtime_ns=item.mtime_ns,\n                        availability=availability,\n                        last_seen_at=now,\n                        updated_at=now,\n                        device_id=item.device_id,\n                        inode=item.inode,\n                        normalized_path_cache=rel.lower(),\n                    )\n                )\n                fts_ids.append(prior.id)\n                updated += 1\n\n        if index % 50 == 0 or index == len(discovered):\n            jobs_repo.update(\n                replace(\n                    job,\n                    stage=\"upsert\",\n                    progress_current=index,\n                    progress_total=len(discovered),\n                )\n            )\n\n    # Mark unseen as missing only after successful enumeration.\n    missing = 0\n    for rel, prior in existing.items():\n        if rel in seen_paths:\n            continue\n        samples_repo.update(\n            replace(\n                prior,\n                availability=SampleAvailability.MISSING,\n                updated_at=now,\n            )\n        )\n        missing += 1\n\n    for sample_id in fts_ids:\n        search.refresh_sample(sample_id)\n\n    sources_repo.update(\n        replace(\n            source,\n            status=SourceStatus.ONLINE if source.enabled else SourceStatus.DISABLED,\n            last_scan_completed_at=now,\n            last_seen_at=now,\n            updated_at=now,\n        )\n    )\n    completed = replace(\n        job,\n        state=JobState.COMPLETED,\n        stage=\"commit\",\n        completed_at=now,\n        error_code=None,\n        progress_current=len(discovered),\n        progress_total=len(discovered),\n        summary_json=json.dumps(\n            {\n                \"inserted\": inserted,\n                \"updated\": updated,\n                \"unchanged\": unchanged,\n                \"missing\": missing,\n                \"discovered\": len(discovered),\n                \"mode\": str(mode),\n            }\n        ),\n    )\n    jobs_repo.update(completed)\n    return completed\n","isEmpty":false,"exceededLimit":false,"totalLines":320,"fileSize":9589,"path":"/home/sean/Documents/experiments/csw-041026/.dreadnought/scratch/koffer/work/src/koffer/jobs/source_scan.py","readRange":{"startLine":1,"endLine":320},"relatedCursorRulePaths":[],"relatedCursorRules":[]}}},"hookAdditionalContexts":[],"toolCallId":"call-16108435-7250-495c-881c-4414fa4b0cc0-11\nfc_57831a00-a0ba-9a45-8bfd-d24806b9f69a_4","startedAtMs":"1791146630379","completedAtMs":"1791146630506"},"model_call_id":"ce4ebe14-eff3-46b0-8fe6-d15554746bc6-2-1ld8","session_id":"0efa2feb-be94-4c2a-89bc-95307f60fed3","timestamp_ms":1791146630479}
