{"type":"tool_call","subtype":"started","call_id":"call-2c1c74eb-843b-40cc-89f3-2f1cadb6e8f8-50\nfc_ae283661-89f8-9761-a552-9ca244e3b09d_0","tool_call":{"editToolCall":{"args":{"path":"/home/sean/Documents/experiments/csw-041026/.dreadnought/scratch/koffer/work/scripts/generate_test_audio.py","streamContent":"#!/usr/bin/env python3\n\"\"\"Generate small deterministic audio fixtures for tests (docs/20).\"\"\"\n\nfrom __future__ import annotations\n\nimport argparse\nimport math\nimport struct\nimport wave\nfrom pathlib import Path\n\n\ndef write_sine_wav(\n    path: Path,\n    *,\n    duration_s: float = 1.0,\n    sample_rate: int = 44100,\n    channels: int = 1,\n    frequency_hz: float = 440.0,\n    amplitude: float = 0.2,\n) -> Path:\n    \"\"\"Write a PCM16 WAV sine tone; returns ``path``.\"\"\"\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    frame_count = max(1, int(round(duration_s * sample_rate)))\n    with wave.open(str(path), \"wb\") as handle:\n        handle.setnchannels(channels)\n        handle.setsampwidth(2)\n        handle.setframerate(sample_rate)\n        frames = bytearray()\n        for index in range(frame_count):\n            sample = int(\n                32767.0\n                * amplitude\n                * math.sin(2.0 * math.pi * frequency_hz * index / sample_rate)\n            )\n            packed = struct.pack(\"<h\", sample)\n            for _ in range(channels):\n                frames.extend(packed)\n        handle.writeframes(frames)\n    return path\n\n\ndef write_silence_wav(\n    path: Path,\n    *,\n    duration_s: float = 0.25,\n    sample_rate: int = 44100,\n    channels: int = 1,\n) -> Path:\n    \"\"\"Write a silent PCM16 WAV.\"\"\"\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    frame_count = max(1, int(round(duration_s * sample_rate)))\n    with wave.open(str(path), \"wb\") as handle:\n        handle.setnchannels(channels)\n        handle.setsampwidth(2)\n        handle.setframerate(sample_rate)\n        handle.writeframes(b\"\\x00\\x00\" * frame_count * channels)\n    return path\n\n\ndef write_malformed_wav(path: Path) -> Path:\n    \"\"\"Write bytes that look audio-ish but are not a valid WAV container.\"\"\"\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_bytes(b\"RIFF....NOTAWAVEFILE\")\n    return path\n\n\ndef generate_default_set(output_dir: Path) -> dict[str, Path]:\n    \"\"\"Generate the Phase-2 probe fixture set under ``output_dir``.\"\"\"\n    root = Path(output_dir)\n    root.mkdir(parents=True, exist_ok=True)\n    return {\n        \"mono_sine\": write_sine_wav(root / \"mono_sine_1s.wav\", channels=1, duration_s=1.0),\n        \"stereo_sine\": write_sine_wav(root / \"stereo_sine_1s.wav\", channels=2, duration_s=1.0),\n        \"silence\": write_silence_wav(root / \"silence_250ms.wav\", duration_s=0.25),\n        \"malformed\": write_malformed_wav(root / \"malformed.wav\"),\n    }\n\n\ndef main(argv: list[str] | None = None) -> int:\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\n        \"--output-dir\",\n        type=Path,\n        default=Path(\"fixtures/generated\"),\n        help=\"Directory for generated fixture files\",\n    )\n    args = parser.parse_args(argv)\n    written = generate_default_set(args.output_dir)\n    for name, path in written.items():\n        print(f\"{name}: {path}\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n"}},"hookAdditionalContexts":[],"toolCallId":"call-2c1c74eb-843b-40cc-89f3-2f1cadb6e8f8-50\nfc_ae283661-89f8-9761-a552-9ca244e3b09d_0","startedAtMs":"1791146767347"},"model_call_id":"ce4ebe14-eff3-46b0-8fe6-d15554746bc6-9-ahzn","session_id":"0efa2feb-be94-4c2a-89bc-95307f60fed3","timestamp_ms":1791146767462}
