ive_path=relative_path,\n        normalized_path_cache=relative_path,\n        filename=filename,\n        extension=\"wav\",\n        size_bytes=size_bytes,\n        mtime_ns=1_700_000_000_000_000_000,\n        availability=SampleAvailability.ONLINE,\n        favorite=favorite,\n        first_seen_at=now,\n        last_seen_at=now,\n        created_at=now,\n        updated_at=now,\n        source_id=source_id,\n    )\n\n\ndef _seed_classification(\n    repo: ClassificationRepository,\n    sample_id: EntityId,\n    dimension: ClassificationDimension,\n    value: str,\n) -> None:\n    now = utc_now_iso()\n    repo.create(\n        Classification(\n            id=new_entity_id(),\n            sample_id=sample_id,\n            dimension=dimension,\n            value=value,\n            source=ClassificationSource.USER,\n            created_at=now,\n            updated_at=now,\n        )\n    )\n\n\ndef _seed_tech(\n    repo: TechnicalMetadataRepository,\n    sample_id: EntityId,\n    *,\n    duration_ms: int,\n    channels: int = 2,\n) -> None:\n    repo.upsert(\n        TechnicalMetadata(\n            sample_id=sample_id,\n            container_format=\"wav\",\n            codec=\"pcm_s16le\",\n            duration_ms=duration_ms,\n            sample_rate_hz=44100,\n            channels=channels,\n            probe_version=\"test\",\n            probed_at=utc_now_iso(),\n        )\n    )\n\n\ndef _seed_feature(\n    conn: sqlite3.Connection,\n    sample_id: EntityId,\n    *,\n    name: str,\n    value_json: str,\n) -> None:\n    run_id = new_entity_id()\n    now = utc_now_iso()\n    conn.execute(\n        \"\"\"\n        INSERT INTO analysis_runs (\n            id, sample_id, pipeline_version, source_fingerprint, state,\n            started_at, completed_at, error_code\n        ) VALUES (?, ?, 'test', 'fp', 'completed', ?, ?, NULL)\n        \"\"\",\n        (str(run_id), str(sample_id), now, now),\n    )\n    conn.execute(\n        \"\"\"\n        INSERT INTO analysis