n        \"\"\"Rows currently held in the page cache.\"\"\"\n        return sum(len(page) for page in self._pages.values())\n\n    def set_query(self, query: SampleQuery) -> None:\n        \"\"\"Replace active query and drop cached pages.\"\"\"\n        self.beginResetModel()\n        self._query = query\n        self._pages.clear()\n        self._total = self._search.count(query)\n        self.endResetModel()\n\n    def set_sort(self, field: SortField, direction: SortDirection = SortDirection.ASC) -> None:\n        \"\"\"Update sort and refresh.\"\"\"\n        self.set_query(\n            SampleQuery(\n                version=self._query.version,\n                text=self._query.text,\n                filters=self._query.filters,\n                sort=SortSpec(field=field, direction=direction),\n            )\n        )\n\n    def refresh(self) -> None:\n        \"\"\"Re-count and clear cache for the current query.\"\"\"\n        self.set_query(self._query)\n\n    def rowCount(self, parent: _Index = QModelIndex()) -> int:  # noqa: N802\n        if parent.isValid():\n            return 0\n        return self._total\n\n    def columnCount(self, parent: _Index = QModelIndex()) -> int:  # noqa: N802\n        if parent.isValid():\n            return 0\n        return len(_COLUMNS)\n\n    def headerData(  # noqa: N802\n        self,\n        section: int,\n        orientation: Qt.Orientation,\n        role: int = int(Qt.ItemDataRole.DisplayRole),\n    ) -> object:\n        if role != int(Qt.ItemDataRole.DisplayRole):\n            return None\n        if orientation == Qt.Orientation.Horizontal and 0 <= section < len(_COLUMNS):\n            return _COLUMNS[section][1]\n        return None\n\n    def data(  # noqa: N802\n        self,\n        index: _Index,\n        role: int = int(Qt.ItemDataRole.DisplayRole),\n    ) -> object:\n        if not index.isValid() or role != int(Qt.ItemDataRole.DisplayRole):\n            return None\n        row = self._row_at(index.row())\n        if row is None:\n            return None\n        key = _COLUMNS[index.column()][0]\n        return _display_value(row, key)"}},"hookAdditionalContexts":[],"toolCallId":"call-a074d523-06af-4fe5-95dc-5e563b2ab88f-82\nfc_p3vYLcf-3LYxF7-b76d2028-aws_ue1_2","startedAtMs":"1791147153714"},"model_call_id":"0a6b867e-938d-4b0f-8771-08819be01884-22-unlf","session_id":"5222bea2-79b2-4024-a20f-aedf4574ad7e","timestamp_ms":1791147163083}
